      "compatibility.compatibilityCenterStandard": {
        "registryId": "compatibility.compatibilityCenterStandard",
        "introducedIn": "0.27.0",
        "changedIn": [
          "0.28.0",
          "0.37.0",
          "1.0.0"
        ],
        "deprecatedIn": [],
        "removedIn": [],
        "latestRelatedRelease": "1.0.0",
        "entries": [
          {
            "entryId": "chg_v1_runtime_truth",
            "releaseVersion": "1.0.0",
            "category": "changed",
            "title": "Registry production stability is explicitly separated from deployment status of Site Runtime/SDK, Customer CMS, NEXT F Admin and API runtimes, which retain truthful unknown/not-declared states where evidence is absent."
          },
          {
            "entryId": "chg_v1_stable_policy",
            "releaseVersion": "1.0.0",
            "category": "changed",
            "title": "The coordinated Contract Registry enters the production-current support train with active SemVer, compatibility, deprecation and migration policies."
          },
          {
            "entryId": "chg_b83e748a648cb4",
            "releaseVersion": "0.37.0",
            "category": "changed",
            "title": "V0.37.0 is designated Release Candidate only when blocking QA failures are zero; V1.0.0 remains reserved for Phase 37 Production Acceptance."
          },
          {
            "entryId": "chg_06d58db1c3739a",
            "releaseVersion": "0.28.0",
            "category": "changed",
            "title": "Contract Diff, Compatibility Center, Relationship Explorer and Global Search regenerated against the V0.28.0 Registry."
          },
          {
            "entryId": "chg_843ab58496f01e",
            "releaseVersion": "0.28.0",
            "category": "integrity",
            "title": "Release notes never replace exact Contract Diff or Compatibility evidence."
          },
          {
            "entryId": "chg_84f8d2bf6d60a1",
            "releaseVersion": "0.28.0",
            "category": "fixed",
            "title": "Phase 26 compatibility regression validation now preserves its substantive checks while accepting coordinated later pre-V1 releases instead of hard-coding V0.27.0."
          },
          {
            "entryId": "chg_ea8b013164ca6a",
            "releaseVersion": "0.28.0",
            "category": "internal",
            "title": "A forward current-regression gate now validates Search, Relationships, Diff, Compatibility and Changelog together while historical phase-acceptance scripts remain preserved as release snapshots."
          },
          {
            "entryId": "chg_efe090d9eb233f",
            "releaseVersion": "0.28.0",
            "category": "added",
            "title": "Release detail views with categorized notes, evidence status, support/compatibility context and links to Contract Diff."
          }
        ]
      },
